// Keep the reading surface quiet; optional controls live in two small menus.
(()=>{
 const $=s=>document.querySelector(s);
 const menu=document.createElement('dialog');menu.id='book-options';menu.innerHTML='<button class="dialog-close" aria-label="Close book options">×</button><div class="eyebrow">MAKE IT YOURS</div><h2>Book & voice.</h2><div class="book-options-list"></div>';
 document.body.append(menu);menu.querySelector('.dialog-close').onclick=()=>menu.close();const list=menu.querySelector('.book-options-list');
 for(const id of ['open-paper-settings','customize-current','save-spread','voice-settings','natural-voice-settings','close-book','leave-workspace']){const button=$('#'+id);if(button){button.dataset.bookAction='true';list.append(button)}}
 $('#open-paper-settings').textContent='Paper & page color';$('#customize-current').textContent='Cover & title';$('#save-spread').textContent='Keep this entry';$('#voice-settings').textContent='Microphone & Wispr Flow';$('#close-book').textContent='Close the cover';$('#leave-workspace').textContent='Return home';
 menu.addEventListener('click',event=>{if(event.target.closest('[data-book-action]'))menu.close()},true);
 const open=document.createElement('button');open.id='open-book-options';open.textContent='Book ⋯';open.setAttribute('aria-haspopup','dialog');open.onclick=()=>menu.showModal();$('.desk-top-actions').append(open);
 const undo=document.createElement('button');undo.id='undo-book-action';undo.textContent='↶ Undo';undo.setAttribute('aria-label','Undo last supported edit');undo.onclick=()=>window.diaryConversation.send('Diary, undo');$('.conversation-actions').append(undo);
 const note=$('#add-sticky-chat');note.textContent='Sticky note';note.removeAttribute('title');$('#manual-tools .scrap-actions').prepend(note);
 $('#manual-tools h2').textContent='Add a memory.';$('#manual-tools p').textContent='A note, a photo, a recording, or a little piece of your day.';$('#other-tools').textContent='＋ Add';
 $('#manual-tools').addEventListener('click',event=>{if(event.target.closest('.scrap-actions button'))$('#manual-tools').close()},true);
 const recording=document.createElement('button');recording.id='add-recording';recording.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><rect x="9" y="3" width="6" height="11" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8"/></svg><span>Voice recording</span><small>Upload audio · up to 2 MB</small>';const recordingFile=document.createElement('input');recordingFile.id='recording-file';recordingFile.type='file';recordingFile.accept='audio/*,.mp3,.wav,.m4a,.ogg,.oga,.aac,.flac,.opus';recordingFile.hidden=true;$('#diary-view').append(recordingFile);recording.onclick=()=>recordingFile.click();recordingFile.onchange=async event=>{await addDiaryMedia(event.target.files,true);event.target.value=''};$('#manual-tools .scrap-actions').append(recording);const media=$('#add-photo');media.querySelector('span').textContent='Photo / video';media.setAttribute('aria-label','Upload a photo or video');media.title='Upload a photo or video';media.onclick=()=>{const input=$('#media-file');input.accept='image/*,video/*';input.click()};const tip=document.createElement('p');tip.id='recording-upload-tip';tip.textContent='A recording appears on the page with a play button. You can add or dictate its caption.';$('#manual-tools .scrap-actions').after(tip);
 const form=$('#conversation-form');form.querySelector('label').textContent='Tell your story, or ask for a change';$('#voice-command-input').placeholder='What would you like to write or change?';$('#send-diary').textContent='Send';
 const natural=$('#natural-voice-dialog');natural.querySelector('h2').textContent='Voice & understanding.';natural.querySelector('p').textContent='Tell your story or ask for an edit. If a request is unclear, the book asks you to clarify.';natural.querySelector('.natural-examples')?.remove();
 const privacy=document.createElement('details');privacy.className='connection-details';privacy.innerHTML='<summary>Connection & privacy</summary>';const setup=natural.querySelector('.natural-setup');privacy.append(setup);const paragraphs=natural.querySelectorAll(':scope > p');const last=paragraphs[paragraphs.length-1];if(last&&last!==$('#natural-connection')){last.textContent='Built-in Wispr sends microphone audio through this website’s server to Wispr Flow. Browser dictation uses a separate speech service. Natural understanding sends your words and limited book context to the configured AI provider.';privacy.append(last)}natural.append(privacy);
 window.showBookControls=()=>menu.showModal();window.closeBookControls=()=>menu.close();
 for(const selector of ['#voice-guide','#voice-guide-dialog','#book-control-guide','#book-control-dialog','#open-book-controls','#homepage-voice-manual','.demo-shortcuts','.hero-footnote','.sample-link'])$(selector)?.remove();
 for(const selector of ['#paper-settings .paper-command'])$(selector)?.remove();
})();
